const isRecord = (value: unknown): value is RuntimeRecord =>
  value !== null && typeof value === "object" && !Array.isArray(value);

const hasType = (schema: RuntimeSchema, type: string): boolean =>
  schema.type === type || (Array.isArray(schema.type) && schema.type.includes(type));

const resolveSchema = (schema: RuntimeSchema): RuntimeSchema | null => {
  const seen = new Set<string>();
  let current = schema;
  while (current.ref) {
    if (seen.has(current.ref)) return null;
    seen.add(current.ref);
    const referenced = modelSchemas[current.ref];
    if (!referenced) return current;
    current = referenced;
  }
  return current;
};

const matchesShape = (value: unknown, schema: RuntimeSchema): boolean => {
  const resolved = resolveSchema(schema);
  if (!resolved) return true;
  if (value === null) return resolved.nullable === true || hasType(resolved, "null");
  // An object missing a branch's required member still belongs to that branch:
  // validating it there is what refuses the body.
  if (hasType(resolved, "object") || resolved.properties) return isRecord(value);
  if (hasType(resolved, "array")) return Array.isArray(value);
  if (hasType(resolved, "string")) return typeof value === "string";
  if (hasType(resolved, "integer")) return Number.isInteger(value);
  if (hasType(resolved, "number")) return typeof value === "number";
  if (hasType(resolved, "boolean")) return typeof value === "boolean";
  return true;
};

const childField = (field: string, property: string): string =>
  field ? `${field}.${property}` : property;

const itemField = (field: string, index: number): string => `${field}[${index}]`;

const validateNode = (value: unknown, schema: RuntimeSchema, field: string): unknown => {
  if (value === null && schema.nullable === true) return value;
  const resolved = resolveSchema(schema);
  if (!resolved) return value;
  if (resolved.openTag && isRecord(value)) {
    const tag = value[resolved.openTag[0]];
    // A member whose tag names no branch is kept as received.
    if (typeof tag === "string" && !resolved.openTag[1].includes(tag)) return value;
  }

  if (resolved.allOf) {
    for (const member of resolved.allOf) validateNode(value, member, field);
  }

  const alternatives = resolved.oneOf ?? resolved.anyOf;
  if (alternatives) {
    const applicable = alternatives.filter((member) => matchesShape(value, member));
    if (applicable.length === 0) return value;
    let firstError: unknown;
    for (const member of applicable) {
      try {
        return validateNode(value, member, field);
      } catch (error) {
        firstError ??= error;
      }
    }
    if (firstError instanceof Error) throw firstError;
  }

  if (isRecord(value)) {
    for (const property of resolved.required ?? []) {
      const missing = !Object.prototype.hasOwnProperty.call(value, property);
      if (missing || (value[property] === null && !resolved.nullableRequired?.includes(property))) {
        const member = childField(field, property);
        throw new SdkValidationError(
          member,
          "required",
          `Required property '${member}' is ${missing ? "missing" : "null"}`,
        );
      }
    }

    for (const [property, propertySchema] of Object.entries(resolved.properties ?? {})) {
      if (Object.prototype.hasOwnProperty.call(value, property)) {
        validateNode(value[property], propertySchema, childField(field, property));
      }
    }
    if (resolved.additionalProperties) {
      for (const [property, propertyValue] of Object.entries(value)) {
        if (!(property in (resolved.properties ?? {}))) {
          validateNode(propertyValue, resolved.additionalProperties, childField(field, property));
        }
      }
    }
  }

  if (Array.isArray(value) && resolved.items) {
    value.forEach((item, index) =>
      validateNode(item, resolved.items as RuntimeSchema, itemField(field, index)),
    );
  }

  if (resolved.enum) validateEnum(field, value, resolved.enum);

  return value;
};

/** Validates strict enum, base64 and required-member constraints on a raw operation response. */
export function decodeResponseEnums<T>(value: T, schema: RuntimeSchema): T {
  return validateNode(value, schema, "") as T;
}

// Each error model `SdkHttpError.data` can hold, by the name its status maps to.
const errorModelSchemas: Readonly<Record<string, RuntimeSchema>> = {
  ClerkErrors: { ref: "ClerkErrors" },
};

/** Whether an error body fits the model its status declares. */
export function errorBodyFits(value: unknown, model: string): boolean {
  const schema = errorModelSchemas[model];
  if (!schema) return true;
  try {
    validateNode(value, schema, "");
  } catch {
    return false;
  }
  return matchesShape(value, schema);
}
